42: /** Standard Elo expectation for a single pairing. */
43: export function expectedScore(rating: number, opponentRating: number): number {
44:   return 1 / (1 + Math.pow(10, (opponentRating - rating) / 400));
45: }
46: 
47: /** Fresh accounts move fast, elite accounts move slowly; bots can be damped further. */
48: export function kFactorFor(participant: RatingParticipant, options: RatingOptions = {}): number {
49:   const provisionalMatches = options.provisionalMatches ?? 10;
50:   const played = participant.matchesPlayed ?? provisionalMatches;
51:   let factor = options.baseK ?? 24;
52:   if (played < provisionalMatches) factor = options.provisionalK ?? 40;
53:   else if (participant.rating >= (options.eliteRating ?? 2200)) factor = options.eliteK ?? 16;
54:   if (participant.kind === 'bot') factor *= options.botKMultiplier ?? 1;
55:   return factor;
56: }
