58: /**
59:  * Multiplayer Elo: each player is scored against every opponent in the lobby and the
60:  * pairwise results are averaged, so an eight player match stays comparable to a duel.
61:  * With equal K factors the raw deltas of a match sum to zero.
62:  */
63: export function computeMatchRatings(
64:   participants: readonly RatingParticipant[],
65:   options: RatingOptions = {},
66: ): RatingChange[] {
67:   const minRating = options.minRating ?? 100;
68:   const maxRating = options.maxRating ?? 3500;
69:   const field = participants.length;
70:   const pairs = Math.max(field - 1, 1);
71: 
72:   return participants.map((participant, index) => {
73:     const kFactor = kFactorFor(participant, options);
74:     let expectedTotal = 0;
75:     let actualTotal = 0;
76: 
77:     participants.forEach((opponent, opponentIndex) => {
78:       if (opponentIndex === index) return;
79:       expectedTotal += expectedScore(participant.rating, opponent.rating);
80:       if (participant.place < opponent.place) actualTotal += 1;
81:       else if (participant.place === opponent.place) actualTotal += 0.5;
82:     });
83: 
84:     const expected = field < 2 ? 0.5 : expectedTotal / pairs;
85:     const actual = field < 2 ? 0.5 : actualTotal / pairs;
86:     const rawDelta = field < 2 ? 0 : kFactor * (actual - expected);
87:     const ratingAfter = clamp(Math.round(participant.rating + rawDelta), minRating, maxRating);
88: 
89:     return {
90:       playerId: participant.playerId,
91:       place: participant.place,
92:       ratingBefore: participant.rating,
93:       ratingAfter,
94:       delta: ratingAfter - participant.rating,
95:       rawDelta,
96:       expectedScore: expected,
97:       actualScore: actual,
98:       kFactor,
99:     };
100:   });
101: }
